document.querySelectorAll('#cases [data-project]').forEach(card=>card.addEventListener('click',event=>{event.preventDefault();const title=card.querySelector('p').textContent;const src=card.getAttribute('href');const alt=card.querySelector('img').alt;const content=document.querySelector('#detailContent');content.replaceChildren();const heading=document.createElement('h2');heading.textContent=title;const image=document.createElement('img');image.src=src;image.alt=alt;image.className='project-full-image';const action=document.createElement('a');action.href='/contact.html#quote';action.className='gold';action.textContent='DISCUSS YOUR PROJECT →';content.append(heading,image,action);document.querySelector('#detail').showModal()}));